-- Target DB: date-project (Python). Pure ASCII on purpose (Windows mysql client defaults to gbk);
-- Chinese values are written as UTF-8 hex literals.
-- eBay "Friday data" report (Operations / eBay / Data report): two sheets rebuilt every Friday morning from data
-- the system already pulls; only the latest issue is kept (each run replaces the previous one, no history):
--   * listing stock check (one row per online eBay listing) from ods_ebay_store_listing_latest;
--   * overseas stock (one row per GoodCang regional warehouse SKU with sellable > 0) from
--     ods_goodcang_product_inventory_latest, plus the listing item ids of every store.
-- ebay_store_main_site holds each eBay store's planned main site (seeded from the sheet the team used so far,
-- maintained on the page afterwards). Store names are matched by a key that ignores case and punctuation
-- (autoteilefastship = autoteile-fast-ship).
-- Only creates tables, seeds the store list (INSERT IGNORE, never overwrites edits) and registers the scheduler
-- task; idempotent, changes nothing else.
USE `date-project`;
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `ebay_store_main_site` (
  `store_key` VARCHAR(64) NOT NULL COMMENT 'lower case letters and digits of the store name',
  `store_name` VARCHAR(128) NOT NULL COMMENT 'display name',
  `main_site` CHAR(2) NOT NULL COMMENT 'DE / UK / US',
  `second_site` CHAR(2) NULL,
  `note` VARCHAR(255) NULL,
  `company` VARCHAR(255) NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `updated_by` VARCHAR(64) NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`store_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='eBay store planned main site';

