CREATE TABLE IF NOT EXISTS `ebay_friday_report_run` (
  `report_date` DATE NOT NULL COMMENT 'generation date (Beijing time)',
  `generated_at` DATETIME NOT NULL,
  `listing_month` CHAR(7) NULL COMMENT 'stat_month of the listing batch used',
  `listing_pulled_at` DATETIME NULL,
  `goodcang_pulled_at` DATETIME NULL,
  `owner_rule_month` CHAR(7) NULL,
  `listing_rows` INT NOT NULL DEFAULT 0,
  `stock_rows` INT NOT NULL DEFAULT 0,
  `store_columns_json` JSON NULL COMMENT 'ordered store columns of the overseas stock sheet',
  `summary_json` JSON NULL,
  `generated_by` VARCHAR(64) NULL,
  PRIMARY KEY (`report_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='eBay Friday report runs';

CREATE TABLE IF NOT EXISTS `ebay_friday_report_listing` (
  `report_date` DATE NOT NULL,
  `item_id` VARCHAR(32) NOT NULL,
  `sku` VARCHAR(255) NULL,
  `store_name` VARCHAR(128) NULL,
  `online_qty` INT NOT NULL DEFAULT 0,
  `sold_qty` INT NOT NULL DEFAULT 0,
  `listing_site` VARCHAR(16) NULL COMMENT 'site as returned by eBay',
  `start_time` DATETIME NULL COMMENT 'listing start time (Beijing time)',
  `brand` VARCHAR(32) NULL,
  `mid_code` VARCHAR(32) NULL,
  `site` CHAR(2) NULL COMMENT 'UK / US / DE',
  `principal_name` VARCHAR(64) NULL,
  `is_used` TINYINT NOT NULL DEFAULT 0,
  `overseas_stock` INT NOT NULL DEFAULT 0 COMMENT 'GoodCang sellable summed by mid code + site + used',
  `plan_site` CHAR(2) NULL,
  `site_match` TINYINT NULL COMMENT '1 = T, 0 = F, NULL = store has no main site',
  PRIMARY KEY (`report_date`,`item_id`),
  KEY `idx_report_store` (`report_date`,`store_name`),
  KEY `idx_report_sku` (`report_date`,`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='eBay Friday report: listing stock check';

CREATE TABLE IF NOT EXISTS `ebay_friday_report_stock` (
  `report_date` DATE NOT NULL,
  `row_no` INT NOT NULL,
  `product_sku` VARCHAR(255) NOT NULL COMMENT 'GoodCang SKU, JMH-...',
  `product_type` VARCHAR(32) NULL,
  `product_barcode` VARCHAR(255) NULL,
  `compliance_status` VARCHAR(32) NULL,
  `product_title` VARCHAR(1000) NULL,
  `warehouse_code` VARCHAR(32) NULL,
  `warehouse_desc` VARCHAR(255) NULL,
  `warning_qty` INT NULL,
  `onway` INT NULL,
  `total_onway` INT NULL,
  `transfer_onway` INT NULL,
  `freeze` INT NULL,
  `sellable` INT NULL,
  `reserved` INT NULL,
  `shipped` INT NULL,
  `unsellable` INT NULL,
  `unsellable_reserved` INT NULL,
  `unsellable_shipped` INT NULL,
  `site` CHAR(2) NULL,
  `sku` VARCHAR(255) NULL COMMENT 'JMH replaced by the brand',
  `mid_code` VARCHAR(32) NULL,
  `brand` VARCHAR(32) NULL,
  `is_used` TINYINT NOT NULL DEFAULT 0,
  `no_link` TINYINT NOT NULL DEFAULT 0 COMMENT '1 = no online listing in any store',
  `principal_name` VARCHAR(64) NULL,
  `store_items_json` JSON NULL COMMENT 'store_key -> "item, item:sold"',
  PRIMARY KEY (`report_date`,`row_no`),
  KEY `idx_report_sku` (`report_date`,`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='eBay Friday report: overseas stock';

INSERT INTO `scheduler_task` (`task_code`, `task_name`, `cron_expression`, `enabled`, `description`)
VALUES ('ebay_friday_report_generate', CONVERT(X'65426179E591A8E4BA94E695B0E68DAEE7949FE68890' USING utf8mb4), '0 0 6 ? * FRI', 1,
        CONVERT(X'' USING utf8mb4))
ON DUPLICATE KEY UPDATE `task_name`=VALUES(`task_name`), `cron_expression`=VALUES(`cron_expression`),
  `description`=VALUES(`description`);
